import React from 'react';
import { Link, useStaticQuery, graphql } from 'gatsby';
import { getArticlePath } from '../utils/articlePath';
import OptimizedImage from './OptimizedImage';
import { formatDate } from '../utils/dateUtils';

interface FooterArticle {
  id: string;
  frontmatter: {
    slug: string;
    title: string;
    featuredImage: string;
    tags: string[];
    publishedAt: string;
    series?: {
      name: string;
    };
  };
}

interface FooterData {
  site: {
    siteMetadata: {
      title: string;
    };
  };
  workArticles: {
    nodes: FooterArticle[];
  };
  familyArticles: {
    nodes: FooterArticle[];
  };
  aiArticles: {
    nodes: FooterArticle[];
  };
}

const Footer: React.FC = () => {
  const data = useStaticQuery<FooterData>(graphql`
    query FooterQuery {
      site {
        siteMetadata {
          title
        }
      }
      workArticles: allMarkdownRemark(
        filter: { frontmatter: { tags: { in: ["work"] }, slug: { ne: null }, draft: { ne: true } }, fileAbsolutePath: { regex: "//content/(posts|reviews|brewing)/" } }
        limit: 3
        sort: { frontmatter: { publishedAt: DESC } }
      ) {
        nodes {
          id
          frontmatter {
            slug
            title
            featuredImage
            tags
            publishedAt
            series {
              name
            }
          }
        }
      }
      familyArticles: allMarkdownRemark(
        filter: { frontmatter: { tags: { in: ["family"] }, slug: { ne: null }, draft: { ne: true } }, fileAbsolutePath: { regex: "//content/(posts|reviews|brewing)/" } }
        limit: 3
        sort: { frontmatter: { publishedAt: DESC } }
      ) {
        nodes {
          id
          frontmatter {
            slug
            title
            featuredImage
            tags
            publishedAt
            series {
              name
            }
          }
        }
      }
      aiArticles: allMarkdownRemark(
        filter: { frontmatter: { tags: { in: ["ai"] }, slug: { ne: null }, draft: { ne: true } }, fileAbsolutePath: { regex: "//content/(posts|reviews)/" } }
        limit: 3
        sort: { frontmatter: { publishedAt: DESC } }
      ) {
        nodes {
          id
          frontmatter {
            slug
            title
            featuredImage
            tags
            publishedAt
            series {
              name
            }
          }
        }
      }
    }
  `);

  const { title } = data.site.siteMetadata;
  const workArticles = data.workArticles.nodes;
  const familyArticles = data.familyArticles.nodes;
  const aiArticles = data.aiArticles.nodes;

  return (
    <footer id="colophon" className="site-footer">
      <div className="hm-footer-widget-area">
        <div className="hm-container hm-footer-widgets-inner">
          {/* AI Column */}
          <div className="hm-footer-column">
            <section className="widget widget_hybridmag_sidebar_posts">
              <div className="hm-sidebar-posts">
                <h2 className="widget-title">AI</h2>
                {aiArticles.map((article) => {
                  const isReview = article.frontmatter.tags?.some(t => t.toLowerCase() === 'reviews');
                  const isBrewing = article.frontmatter.tags?.some(t => t.toLowerCase() === 'brewing');
                  const articlePath = getArticlePath(article.frontmatter.slug, !!article.frontmatter.series?.name, isReview, isBrewing);
                  return (
                    <div key={article.id} className="hms-post clearfix">
                  <div className="hms-thumb">
                    <Link to={articlePath}>
                      <OptimizedImage
                        src={article.frontmatter.featuredImage}
                        alt={article.frontmatter.title}
                        className="attachment-thumbnail size-thumbnail wp-post-image"
                        sizes="64px"
                      />
                    </Link>
                  </div>
                  <div className="hms-details">
                    <h3 className="hms-title">
                      <Link to={articlePath}>{article.title}</Link>
                    </h3>
                    <div className="entry-meta">
                      <time className="entry-date published" dateTime={article.frontmatter.publishedAt}>
                        {formatDate(article.frontmatter.publishedAt)}
                      </time>
                    </div>
                  </div>
                  </div>
                  );
                })}
              </div>
            </section>
          </div>

          {/* Work Column */}
          <div className="hm-footer-column">
            <section className="widget widget_hybridmag_sidebar_posts">
              <div className="hm-sidebar-posts">
                <h2 className="widget-title">Work</h2>
                {workArticles.map((article) => {
                  const isReview = article.frontmatter.tags?.some(t => t.toLowerCase() === 'reviews');
                  const isBrewing = article.frontmatter.tags?.some(t => t.toLowerCase() === 'brewing');
                  const articlePath = getArticlePath(article.frontmatter.slug, !!article.frontmatter.series?.name, isReview, isBrewing);
                  return (
                    <div key={article.id} className="hms-post clearfix">
                  <div className="hms-thumb">
                    <Link to={articlePath}>
                      <OptimizedImage
                        src={article.frontmatter.featuredImage}
                        alt={article.frontmatter.title}
                        className="attachment-thumbnail size-thumbnail wp-post-image"
                        sizes="64px"
                      />
                    </Link>
                  </div>
                  <div className="hms-details">
                    <h3 className="hms-title">
                      <Link to={articlePath}>{article.title}</Link>
                    </h3>
                    <div className="entry-meta">
                      <time className="entry-date published" dateTime={article.frontmatter.publishedAt}>
                        {formatDate(article.frontmatter.publishedAt)}
                      </time>
                    </div>
                  </div>
                  </div>
                  );
                })}
              </div>
            </section>
          </div>

          {/* Family Column */}
          <div className="hm-footer-column">
            <section className="widget widget_hybridmag_sidebar_posts">
              <div className="hm-sidebar-posts">
                <h2 className="widget-title">Family</h2>
                {familyArticles.map((article) => {
                  const isReview = article.frontmatter.tags?.some(t => t.toLowerCase() === 'reviews');
                  const articlePath = getArticlePath(article.frontmatter.slug, !!article.frontmatter.series?.name, isReview);
                  return (
                    <div key={article.id} className="hms-post clearfix">
                  <div className="hms-thumb">
                    <Link to={articlePath}>
                      <OptimizedImage
                        src={article.frontmatter.featuredImage}
                        alt={article.frontmatter.title}
                        className="attachment-thumbnail size-thumbnail wp-post-image"
                        sizes="64px"
                      />
                    </Link>
                  </div>
                  <div className="hms-details">
                    <h3 className="hms-title">
                      <Link to={articlePath}>{article.title}</Link>
                    </h3>
                    <div className="entry-meta">
                      <time className="entry-date published" dateTime={article.frontmatter.publishedAt}>
                        {formatDate(article.frontmatter.publishedAt)}
                      </time>
                    </div>
                  </div>
                  </div>
                  );
                })}
              </div>
            </section>
          </div>
        </div>
      </div>

      {/* Footer Bottom */}
      <div className="hm-footer-bottom">
        <div className="hm-container hm-footer-bottom-content">
          <div className="hm-footer-copyright">
            Copyright © {new Date().getFullYear()} <Link to="/" title={title}>{title}</Link>.
          </div>
          <div className="hm-designer-credit">
            Powered by <a href="https://www.gatsbyjs.com/" target="_blank" rel="noopener noreferrer">Gatsby</a>, <a href="https://themezhut.com/themes/hybridmag/" target="_blank" rel="noopener noreferrer">HybridMag</a> and a team of AI agents.
          </div>
        </div>
      </div>
    </footer>
  );
};

export default Footer;
